import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

layernorm_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void layernorm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N,
    float eps)
{
    int b = blockIdx.x;
    const float* x_ptr = x + (size_t)b * N;
    float* out_ptr = out + (size_t)b * N;
    int N4 = N / 4;
    int rem_start = N4 * 4;
    const float4* x_ptr4 = reinterpret_cast<const float4*>(x_ptr);
    float4* out_ptr4 = reinterpret_cast<float4*>(out_ptr);
    const float4* w_ptr4 = reinterpret_cast<const float4*>(weight);
    const float4* b_ptr4 = reinterpret_cast<const float4*>(bias);
    extern __shared__ float sdata[];
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    float sum = 0.0f;
    float sumsq = 0.0f;
    for (int i = tid; i < N4; i += nthreads) {
        float4 v = x_ptr4[i];
        sum += v.x + v.y + v.z + v.w;
        sumsq += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
    }
    for (int i = rem_start + tid; i < N; i += nthreads) {
        float v = x_ptr[i];
        sum += v;
        sumsq += v * v;
    }
    // warp-level reduction using shuffle instructions
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset);
        sumsq += __shfl_down_sync(mask, sumsq, offset);
    }
    int warp_id = tid >> 5;
    int lane_id = tid & 31;
    int num_warps = (nthreads + 31) >> 5;
    if (lane_id == 0) {
        sdata[warp_id] = sum;
        sdata[num_warps + warp_id] = sumsq;
    }
    __syncthreads();
    __shared__ float mean_s;
    __shared__ float inv_std_s;
    if (tid == 0) {
        float total_sum = 0.0f;
        float total_sumsq = 0.0f;
        for (int w = 0; w < num_warps; w++) {
            total_sum += sdata[w];
            total_sumsq += sdata[num_warps + w];
        }
        float mean = total_sum / N;
        float var = total_sumsq / N - mean * mean;
        if (var < 0.0f) var = 0.0f;
        mean_s = mean;
        inv_std_s = rsqrtf(var + eps);
    }
    __syncthreads();
    float mean = mean_s;
    float inv_std = inv_std_s;
    for (int i = tid; i < N4; i += nthreads) {
        float4 v = x_ptr4[i];
        float4 w = w_ptr4[i];
        float4 bb = b_ptr4[i];
        float4 o;
        o.x = (v.x - mean) * inv_std * w.x + bb.x;
        o.y = (v.y - mean) * inv_std * w.y + bb.y;
        o.z = (v.z - mean) * inv_std * w.z + bb.z;
        o.w = (v.w - mean) * inv_std * w.w + bb.w;
        out_ptr4[i] = o;
    }
    for (int i = rem_start + tid; i < N; i += nthreads) {
        float v = x_ptr[i];
        out_ptr[i] = (v - mean) * inv_std * weight[i] + bias[i];
    }
}

torch::Tensor layernorm_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");

    auto x_contig = x.contiguous();
    auto weight_contig = weight.contiguous();
    auto bias_contig = bias.contiguous();

    int64_t N = weight_contig.numel();
    int64_t total = x_contig.numel();
    int64_t B = total / N;

    auto out = torch::empty_like(x_contig);

    int threads = 1024;
    dim3 grid(B);
    dim3 block(threads);
    size_t shared_mem = 2 * threads * sizeof(float);

    layernorm_kernel<<<grid, block, shared_mem>>>(
        x_contig.data_ptr<float>(),
        weight_contig.data_ptr<float>(),
        bias_contig.data_ptr<float>(),
        out.data_ptr<float>(),
        (int)N,
        (float)eps
    );
    return out;
}
"""

layernorm_cpp_source = r"""
torch::Tensor layernorm_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

layernorm_module = load_inline(
    name="layernorm_module",
    cpp_sources=layernorm_cpp_source,
    cuda_sources=layernorm_source,
    functions=["layernorm_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Layer Normalization using a custom fused CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = 1e-5
        self.layernorm_module = layernorm_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.layernorm_module.layernorm_cuda(x, self.weight, self.bias, self.eps)


batch_size = 16
features = 64
dim1 = 256
dim2 = 256

def get_inputs():
    x = torch.rand(batch_size, features, dim1, dim2).cuda()
    return [x]

def get_init_inputs():
    return [(features, dim1, dim2)]

